const catName = slug => categories.find(c=>c.slug===slug)?.name || slug;
const svg = name => ({heart:'♡',bag:'▣',menu:'☰',close:'×',phone:'☎',search:'⌕',wa:'◉'}[name]||'•');
const escapeHTML = v => String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
