function breadcrumbs(label,parent='Home'){return `<div class="breadcrumbs"><a href="/">${parent}</a><span>/</span><span>${label}</span></div>`}

function categoryCards(){return `<div class="category-grid">${categories.map(c=>`<a class="category-card" href="/products/?category=${c.slug}"><img src="${c.image}" alt="${c.name}" loading="lazy"><div class="category-content"><h3>${c.name}</h3><p>${c.description}</p><span>Explore products</span></div></a>`).join('')}</div>`}

function productCard(p){const wished=wishlist.includes(p.slug);return `<article class="product-card" data-product-card data-name="${escapeHTML(p.name.toLowerCase())}" data-category="${p.category}"><div class="product-media"><a href="/products/${p.slug}/"><img src="${p.image}" alt="${escapeHTML(p.name)}" loading="lazy"></a>${p.featured?'<span class="tag">Featured</span>':''}<button class="icon-btn wish ${wished?'active':''}" data-wish="${p.slug}" aria-label="${wished?'Remove from':'Add to'} wishlist">${svg('heart')}</button></div><div class="product-body"><span class="product-category">${catName(p.category)}</span><h3><a href="/products/${p.slug}/">${escapeHTML(p.name)}</a></h3><p>${escapeHTML(p.description)}</p><div class="price">Contact for Price</div><div class="product-actions"><a class="btn btn-outline btn-sm" href="/products/${p.slug}/">View Details</a><button class="btn btn-secondary btn-sm" data-cart="${p.slug}">Add to Enquiry</button></div></div></article>`}

