function productDetail(p){if(!p)return notFound();const related=products.filter(x=>x.category===p.category&&x.slug!==p.slug).slice(0,3);return shell(`<section class="section-sm"><div class="container">${breadcrumbs(p.name,'Products')}<div class="product-detail"><div class="gallery-main"><img src="${p.image}" alt="${escapeHTML(p.name)}"></div><div class="product-info"><span class="eyebrow">${catName(p.category)}</span><h1>${escapeHTML(p.longName||p.name)}</h1><div class="price">Contact for Price</div><p class="lead">${escapeHTML(p.description)}</p><div class="action-stack"><a class="btn btn-primary" href="${whatsapp(`Hello MobilityOne, I’m interested in ${p.name}. Product page: ${location.href}`)}" target="_blank">Enquire on WhatsApp</a><a class="btn btn-outline" href="/consultation/?product=${p.slug}">Request Consultation</a><button class="btn btn-secondary" data-cart="${p.slug}">Add to Enquiry Cart</button></div><div class="info-note">Product selection, clinical suitability, materials, sizing and fitting must be confirmed through individual assessment. No medical outcome is implied.</div></div></div><div class="tabs" role="tablist"><button class="active" data-tab="overview">Overview</button><button data-tab="features">Product guidance</button><button data-tab="fitting">Fitting information</button><button data-tab="care">Care</button></div><div class="tab-panel" id="tabPanel"><h3>Product overview</h3><p>${escapeHTML(p.description)} MobilityOne can provide available product information and discuss the appropriate next steps during an enquiry.</p></div></div></section>${related.length?`<section class="section soft"><div class="container"><div class="section-head"><div><span class="eyebrow">Continue exploring</span><h2>Related products</h2></div></div><div class="product-grid">${related.map(productCard).join('')}</div></div></section>`:''}`,'Products')}

function aboutPage(){return shell(`<section class="page-hero"><div class="container">${breadcrumbs('About Us')}<span class="eyebrow">About MobilityOne</span><h1>${escapeHTML(content.aboutTitle)}</h1><p class="lead">${escapeHTML(content.aboutText)}</p></div></section><section class="section"><div class="container split"><div><span class="eyebrow">Our approach</span><h2>Individual needs come first</h2><p class="lead">The right product starts with understanding the person, their goals and the fitting requirements of the selected solution.</p><ul class="check-list"><li>Clear, respectful and accessible product information</li><li>Consultation-led guidance for individual requirements</li><li>Direct support across WhatsApp, phone and email</li><li>No unverified price, warranty or medical-performance claims</li></ul></div><div class="about-collage"><img src="/assets/products/category-lower-limb.webp" alt="Lower-limb prosthetic solutions"><img src="/assets/products/category-silicone.webp" alt="Silicone prosthetic solutions"></div></div></section><section class="section soft"><div class="container"><div class="section-head"><div><span class="eyebrow">What we offer</span><h2>Professional mobility support</h2></div></div><div class="feature-grid">${[['Personal consultation','Discuss your requirements and available options.'],['Product guidance','Understand available product categories and their next steps.'],['Fitting coordination','Talk through measurements and fitting where applicable.'],['Direct communication','Reach the team without a complicated purchase process.']].map((x,i)=>`<div class="feature-card"><span class="feature-icon">${['✦','⌁','＋','◌'][i]}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></div></section>`,'About Us')}

function consultationPage(){const pre=new URLSearchParams(location.search).get('product')||'';return shell(`<section class="page-hero"><div class="container">${breadcrumbs('Book Consultation')}<span class="eyebrow">Personal guidance</span><h1>Let’s find the right mobility solution for you</h1><p class="lead">Share a few details and the MobilityOne team can review your request. Submission is an enquiry—not a confirmed appointment.</p></div></section><section class="section"><div class="container split"><div><span class="eyebrow">What to expect</span><h2>A focused first conversation</h2><p class="lead">We’ll use the information you share to understand your interest and coordinate the most appropriate next step.</p><div class="contact-list"><div class="contact-row"><span class="feature-icon">01</span><div><strong>Submit your request</strong><span>Tell us about the product or category you are interested in.</span></div></div><div class="contact-row"><span class="feature-icon">02</span><div><strong>Team review</strong><span>MobilityOne reviews your request before confirming a time.</span></div></div><div class="contact-row"><span class="feature-icon">03</span><div><strong>Follow-up</strong><span>The team contacts you using your preferred method.</span></div></div></div></div><form class="form-card" id="consultationForm"><div class="form-grid"><div class="field"><label for="fullName">Full name *</label><input id="fullName" name="name" required autocomplete="name"></div><div class="field"><label for="phone">Phone number *</label><input id="phone" name="phone" required inputmode="tel" autocomplete="tel"></div><div class="field full"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email"></div><div class="field"><label for="category">Product category *</label><select id="category" name="category" required><option value="">Select a category</option>${categories.map(c=>`<option value="${c.slug}">${c.name}</option>`).join('')}</select></div><div class="field"><label for="product">Interested product</label><select id="product" name="product"><option value="">Not sure yet</option>${products.map(p=>`<option value="${p.slug}" ${pre===p.slug?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="field full"><label for="requirement">Your requirement *</label><textarea id="requirement" name="requirement" required placeholder="Tell us what you would like help with"></textarea></div><div class="field"><label for="date">Preferred date</label><input id="date" name="date" type="date"></div><div class="field"><label for="method">Preferred contact method</label><select id="method" name="method"><option>Phone</option><option>WhatsApp</option><option>Email</option></select></div><label class="consent field full"><input type="checkbox" required><span>I consent to MobilityOne using these details to respond to my enquiry. *</span></label><div class="field full"><button class="btn btn-primary" type="submit">Submit Consultation Request</button><small>You will receive an enquiry reference. The appointment is confirmed only after team follow-up.</small></div></div></form></div></section>`,'Book Consultation')}

function contactPage(){return shell(`<section class="page-hero"><div class="container">${breadcrumbs('Contact Us')}<span class="eyebrow">Talk to the team</span><h1>How can we help?</h1><p class="lead">Contact MobilityOne for product information, consultation and fitting guidance.</p></div></section><section class="section"><div class="container split"><div><h2>Contact MobilityOne</h2><div class="contact-list"><a class="contact-row" href="tel:+${PHONE}"><span class="feature-icon">☎</span><div><strong>Call</strong><span>${PHONE_DISPLAY}</span></div></a><a class="contact-row" href="${whatsapp()}" target="_blank"><span class="feature-icon">◉</span><div><strong>WhatsApp</strong><span>Start a product enquiry</span></div></a><a class="contact-row" href="mailto:${EMAIL}"><span class="feature-icon">@</span><div><strong>Email</strong><span>${EMAIL}</span></div></a><a class="contact-row" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(ADDRESS)}" target="_blank"><span class="feature-icon">⌖</span><div><strong>Visit / Directions</strong><span>${ADDRESS}</span></div></a></div></div><form class="form-card" id="contactForm"><div class="form-grid"><div class="field"><label>Name *</label><input name="name" required autocomplete="name"></div><div class="field"><label>Phone *</label><input name="phone" required inputmode="tel" autocomplete="tel"></div><div class="field full"><label>Email</label><input name="email" type="email" autocomplete="email"></div><div class="field full"><label>How can we help? *</label><textarea name="message" required></textarea></div><label class="consent field full"><input type="checkbox" required><span>I consent to being contacted about this enquiry.</span></label><div class="field full"><button class="btn btn-primary" type="submit">Send Enquiry</button></div></div></form></div></section>`,'Contact')}

const faqs=[['What products does MobilityOne offer?','MobilityOne offers prosthetic and orthotic solutions including artificial limbs, braces, foot supports and custom silicone prostheses.'],['Can I enquire without purchasing online?','Yes. The website is enquiry-based. Contact the team through WhatsApp, email or the website forms.'],['Are custom fittings available?','Custom fitting requirements can be discussed during consultation. Availability depends on the selected product.'],['Where is MobilityOne located?','MobilityOne is based in Ghari Harsaru, Gurugram, Haryana, India.'],['How can I book a consultation?',`Use the consultation form, call ${PHONE_DISPLAY}, or send a WhatsApp message.`],['Are prices shown online?','Products use “Contact for Price” until availability and verified pricing are confirmed by the team.']];
function faqMarkup(){return `<div class="faq-list">${faqs.map((f,i)=>`<div class="faq ${i===0?'open':''}"><button aria-expanded="${i===0?'true':'false'}"><span>${f[0]}</span><span>${i===0?'−':'+'}</span></button><div class="faq-panel"><p>${f[1]}</p></div></div>`).join('')}</div>`}
function faqsPage(){return shell(`<section class="page-hero"><div class="container">${breadcrumbs('FAQs')}<span class="eyebrow">Helpful information</span><h1>Frequently asked questions</h1><p class="lead">Clear answers about MobilityOne products, consultations and enquiries.</p></div></section><section class="section"><div class="container">${faqMarkup()}</div></section>`)}

function policyPage(type){const data={privacy:['Privacy Policy','We collect only the information you submit through enquiry and consultation forms so MobilityOne can respond. This browser-based demonstration stores submissions on this device only; a production deployment requires an approved server-side privacy and retention policy.'],terms:['Terms & Conditions','Website content is general product information and is not medical advice. Product suitability, availability, pricing and fitting requirements must be confirmed directly with MobilityOne.'],shipping:['Shipping & Returns','Shipping, handover, fitting, adjustment, cancellation and return terms depend on the confirmed product and order. No generic warranty or return promise is made on this website. Please confirm the applicable policy before ordering.']}[type];return shell(`<section class="page-hero"><div class="container">${breadcrumbs(data[0])}<span class="eyebrow">MobilityOne information</span><h1>${data[0]}</h1></div></section><section class="section"><div class="container" style="max-width:850px"><h2>Important information</h2><p class="lead">${data[1]}</p><p>For questions, contact <a href="mailto:${EMAIL}">${EMAIL}</a> or call <a href="tel:+${PHONE}">${PHONE_DISPLAY}</a>.</p></div></section>`)}

function adminPage(){return `<div class="admin-shell"><aside class="admin-sidebar"><a class="logo" href="/"><img src="/assets/brand/mobilityone-logo.svg" alt="MobilityOne"></a><nav class="admin-nav">${[['dashboard','Dashboard'],['products','Products'],['enquiries','Enquiries'],['consultations','Consultations'],['content','Website Content'],['seo','SEO Manager']].map(x=>`<button data-admin="${x[0]}" class="${activeAdmin===x[0]?'active':''}">${x[1]}</button>`).join('')}</nav></aside><main class="admin-main" id="adminMain">${adminPanel()}</main></div><div id="toast" class="toast" role="status" aria-live="polite"></div>`}
function adminPanel(){const enquiries=getJSON('m1-enquiries',[]),consults=getJSON('m1-consultations',[]);if(activeAdmin==='products')return `<div class="admin-top"><div><span class="eyebrow">Catalogue</span><h1>Products</h1></div><a class="btn btn-outline" href="/products/">View storefront</a></div><div class="admin-card"><div class="admin-card-head"><h3>Product catalogue</h3><span>${products.length} products</span></div><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Price display</th><th>Status</th><th>Featured</th><th>Edit</th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="table-product"><img src="${p.image}" alt=""><strong>${escapeHTML(p.name)}</strong></div></td><td>${catName(p.category)}</td><td>Contact for Price</td><td><span class="status live">Published</span></td><td>${p.featured?'Yes':'No'}</td><td><button class="btn btn-outline btn-sm" data-edit-product="${p.slug}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;
if(activeAdmin==='enquiries'||activeAdmin==='consultations'){const list=activeAdmin==='enquiries'?enquiries:consults;return `<div class="admin-top"><div><span class="eyebrow">Lead management</span><h1>${activeAdmin==='enquiries'?'Enquiries':'Consultations'}</h1></div></div><div class="admin-card"><table class="data-table"><thead><tr><th>Reference</th><th>Customer</th><th>Contact</th><th>Request</th><th>Status</th><th>Submitted</th></tr></thead><tbody>${list.length?list.map(x=>`<tr><td><strong>${x.ref}</strong></td><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.phone||x.email)}</td><td>${escapeHTML(x.message||x.requirement||x.product||'General')}</td><td><span class="status new">New</span></td><td>${new Date(x.created).toLocaleDateString()}</td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">No ${activeAdmin} yet. New browser submissions will appear here.</div></td></tr>`}</tbody></table></div>`}
if(activeAdmin==='content')return `<div class="admin-top"><div><span class="eyebrow">CMS demo</span><h1>Website content</h1></div></div><form class="admin-card" id="contentForm"><div class="form-grid"><div class="field full"><label>Homepage hero title</label><input name="heroTitle" value="${escapeHTML(content.heroTitle)}"></div><div class="field full"><label>Homepage hero description</label><textarea name="heroText">${escapeHTML(content.heroText)}</textarea></div><div class="field full"><label>About title</label><input name="aboutTitle" value="${escapeHTML(content.aboutTitle)}"></div><div class="field full"><label>About summary</label><textarea name="aboutText">${escapeHTML(content.aboutText)}</textarea></div><div class="field full"><button class="btn btn-primary">Save Changes</button><small>Demo content persists in this browser. Production requires authenticated database-backed publishing.</small></div></div></form>`;
if(activeAdmin==='seo')return `<div class="admin-top"><div><span class="eyebrow">Search foundation</span><h1>SEO Manager</h1></div></div><div class="admin-card"><h3>Implemented foundations</h3><ul class="check-list"><li>Descriptive routes and unique page headings</li><li>Canonical URL, Open Graph metadata and LocalBusiness schema</li><li>XML sitemap and robots.txt</li><li>Optimised WebP product images and semantic alt text</li><li>Admin route excluded from indexing</li></ul><p class="lead">Per-page database metadata, analytics IDs and Search Console verification require production backend/domain configuration.</p></div>`;
return `<div class="admin-top"><div><span class="eyebrow">Admin portal</span><h1>Dashboard</h1></div><a class="btn btn-outline" href="/">View website</a></div><div class="stat-grid"><div class="stat"><span>Total products</span><strong>${products.length}</strong></div><div class="stat"><span>Featured products</span><strong>${products.filter(p=>p.featured).length}</strong></div><div class="stat"><span>New enquiries</span><strong>${enquiries.length}</strong></div><div class="stat"><span>Consultation requests</span><strong>${consults.length}</strong></div></div><div class="admin-card"><div class="admin-card-head"><div><h3>Browser-persistent CMS prototype</h3><p>This admin demonstrates content workflows without pretending to provide secure production authentication.</p></div></div><ul class="check-list"><li>Edit homepage content and see changes on the public site</li><li>Edit product content and featured status</li><li>Review consultation and contact submissions made in this browser</li><li>Use verified public contact links for WhatsApp, email and calls</li></ul></div>`}

function notFound(){return shell(`<section class="page-hero"><div class="container"><span class="eyebrow">404</span><h1>We couldn’t find that page</h1><p class="lead">The page may have moved, or the address may be incomplete.</p><p><a class="btn btn-primary" href="/">Return home</a></p></div></section>`)}

function drawer(){const draw=(type,items)=>`<div class="drawer" id="${type}Drawer"><div class="drawer-backdrop" data-close-drawer></div><aside class="drawer-panel"><div class="drawer-head"><div><span class="eyebrow">${type==='cart'?'Enquiry cart':'Saved products'}</span><h2>${type==='cart'?'Your enquiry':'Wishlist'}</h2></div><button class="icon-btn" data-close-drawer aria-label="Close">×</button></div><div>${items.length?items.map(slug=>{const p=products.find(x=>x.slug===slug);return p?`<div class="cart-line"><img src="${p.image}" alt=""><div><strong>${p.name}</strong><small style="display:block;color:var(--muted)">${catName(p.category)}</small></div><button data-remove="${slug}" data-type="${type}">Remove</button></div>`:''}).join(''):`<div class="empty">No products added yet.</div>`}</div>${type==='cart'&&items.length?`<div class="cart-footer"><a class="btn btn-primary" style="width:100%" target="_blank" href="${whatsapp(`Hello MobilityOne, I’d like to enquire about: ${items.map(s=>products.find(p=>p.slug===s)?.name).filter(Boolean).join(', ')}.`)}">Send Combined WhatsApp Enquiry</a></div>`:''}</aside></div>`;return draw('wishlist',wishlist)+draw('cart',cart)}

function render(){const path=location.pathname.replace(/\/+$/,'')||'/';let html;if(path==='/')html=home();else if(path==='/products')html=productsPage();else if(path.startsWith('/products/'))html=productDetail(products.find(p=>p.slug===path.split('/')[2]));else if(path==='/categories')html=categoriesPage();else if(path==='/about')html=aboutPage();else if(path==='/consultation')html=consultationPage();else if(path==='/contact')html=contactPage();else if(path==='/faqs')html=faqsPage();else if(path==='/admin')html=adminPage();else if(path==='/privacy-policy')html=policyPage('privacy');else if(path==='/terms')html=policyPage('terms');else if(path==='/shipping-returns')html=policyPage('shipping');else html=notFound();document.getElementById('app').innerHTML=html;bind();if(path.startsWith('/products/'))document.title=`${products.find(p=>p.slug===path.split('/')[2])?.name||'Product'} | MobilityOne`;else if(path!=='/')document.title=`${document.querySelector('h1')?.textContent||'MobilityOne'} | MobilityOne`;window.scrollTo(0,0)}

function toast(message){let el=document.getElementById('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function saveCollection(type){if(type==='wishlist')setJSON('m1-wishlist',wishlist);else setJSON('m1-cart',cart)}
function bind(){
  document.querySelectorAll('a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||a.target)return;e.preventDefault();history.pushState({},'',a.getAttribute('href'));render()}));
  const menu=document.getElementById('mobileMenu'),menuBtn=document.getElementById('menuBtn');menuBtn?.addEventListener('click',()=>{menu.classList.toggle('open');document.body.classList.toggle('menu-open');menuBtn.setAttribute('aria-expanded',menu.classList.contains('open'))});
  document.querySelectorAll('[data-wish]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.wish;wishlist=wishlist.includes(s)?wishlist.filter(x=>x!==s):[...wishlist,s];saveCollection('wishlist');toast(wishlist.includes(s)?'Added to wishlist':'Removed from wishlist');render()}));
  document.querySelectorAll('[data-cart]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.cart;if(!cart.includes(s))cart.push(s);saveCollection('cart');toast('Added to enquiry cart');render()}));
  document.querySelectorAll('[data-drawer]').forEach(b=>b.addEventListener('click',()=>document.getElementById(`${b.dataset.drawer}Drawer`)?.classList.add('open')));
  document.querySelectorAll('[data-close-drawer]').forEach(b=>b.addEventListener('click',()=>b.closest('.drawer').classList.remove('open')));
  document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.type==='cart')cart=cart.filter(x=>x!==b.dataset.remove);else wishlist=wishlist.filter(x=>x!==b.dataset.remove);saveCollection(b.dataset.type);render()}));
  document.querySelectorAll('.faq button').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq'),open=item.classList.toggle('open');b.setAttribute('aria-expanded',open);b.lastElementChild.textContent=open?'−':'+'}));
  bindCatalog();bindForms();bindTabs();bindAdmin();
}
function bindCatalog(){const search=document.getElementById('productSearch'),sort=document.getElementById('productSort'),pills=document.querySelectorAll('[data-filter]'),grid=document.getElementById('productGrid');if(!grid)return;let filter=new URLSearchParams(location.search).get('category')||'all';pills.forEach(p=>p.classList.toggle('active',p.dataset.filter===filter));const update=()=>{let list=products.filter(p=>(filter==='all'||p.category===filter)&&p.name.toLowerCase().includes((search.value||'').toLowerCase()));if(sort.value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort.value==='za')list.sort((a,b)=>b.name.localeCompare(a.name));if(sort.value==='featured')list.sort((a,b)=>Number(b.featured)-Number(a.featured));grid.innerHTML=list.length?list.map(productCard).join(''):'<div class="empty">No products match your search.</div>';grid.querySelectorAll('a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();history.pushState({},'',a.href);render()}));grid.querySelectorAll('[data-wish]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.wish;wishlist=wishlist.includes(s)?wishlist.filter(x=>x!==s):[...wishlist,s];saveCollection('wishlist');render()}));grid.querySelectorAll('[data-cart]').forEach(b=>b.addEventListener('click',()=>{if(!cart.includes(b.dataset.cart))cart.push(b.dataset.cart);saveCollection('cart');toast('Added to enquiry cart')}))};search?.addEventListener('input',update);sort?.addEventListener('change',update);pills.forEach(p=>p.addEventListener('click',()=>{filter=p.dataset.filter;pills.forEach(x=>x.classList.toggle('active',x===p));update()}));update()}
function bindForms(){const submit=(form,key,prefix)=>{form.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));const ref=`${prefix}-${String(Date.now()).slice(-6)}`;setJSON(key,[{...data,ref,created:new Date().toISOString()},...getJSON(key,[])]);form.reset();toast(`Request received · ${ref}`)})};const consult=document.getElementById('consultationForm'),contact=document.getElementById('contactForm');if(consult)submit(consult,'m1-consultations','CON');if(contact)submit(contact,'m1-enquiries','ENQ');const cf=document.getElementById('contentForm');cf?.addEventListener('submit',e=>{e.preventDefault();Object.assign(content,Object.fromEntries(new FormData(cf)));setJSON('m1-content',content);toast('Website content saved')})}
function bindTabs(){const panel=document.getElementById('tabPanel');if(!panel)return;const copy={overview:['Product overview','Product information and availability are confirmed during enquiry.'],features:['Product guidance','Exact materials, models, features, sizes and technical specifications must be verified for the selected product.'],fitting:['Fitting information','Measurements and fitting requirements vary by product and individual need. MobilityOne will explain applicable steps during consultation.'],care:['Care & maintenance','Follow the manufacturer’s and clinician’s care instructions supplied with the confirmed product.']};document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));panel.innerHTML=`<h3>${copy[b.dataset.tab][0]}</h3><p>${copy[b.dataset.tab][1]}</p>`}))}
function bindAdmin(){document.querySelectorAll('[data-admin]').forEach(b=>b.addEventListener('click',()=>{activeAdmin=b.dataset.admin;render()}));document.querySelectorAll('[data-edit-product]').forEach(b=>b.addEventListener('click',()=>{const p=products.find(x=>x.slug===b.dataset.editProduct);document.getElementById('adminMain').innerHTML=`<div class="admin-top"><div><span class="eyebrow">Edit product</span><h1>${escapeHTML(p.name)}</h1></div></div><form class="admin-card" id="productEditForm"><input type="hidden" name="slug" value="${p.slug}"><div class="form-grid"><div class="field full"><label>Product name</label><input name="name" value="${escapeHTML(p.name)}"></div><div class="field full"><label>Short description</label><textarea name="description">${escapeHTML(p.description)}</textarea></div><div class="field"><label>Featured product</label><select name="featured"><option value="true" ${p.featured?'selected':''}>Yes</option><option value="false" ${!p.featured?'selected':''}>No</option></select></div><div class="field full"><button class="btn btn-primary">Save Product</button></div></div></form>`;document.getElementById('productEditForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)),edits=getJSON('m1-product-edits',{});edits[data.slug]={name:data.name,description:data.description,featured:data.featured==='true'};setJSON('m1-product-edits',edits);products=baseProducts.map(x=>({...x,...(edits[x.slug]||{})}));activeAdmin='products';render();toast('Product updated')})}))}

window.addEventListener('popstate',render);
render();
